def comps(A,wall=5,conn4=True):
    H,W=A.shape; seen=np.zeros_like(A,dtype=bool); out=[]
    nbrs=[(1,0),(-1,0),(0,1),(0,-1)]+( [] if conn4 else [(1,1),(1,-1),(-1,1),(-1,-1)])
    for i in range(H):
        for j in range(W):
            if A[i,j]==wall and not seen[i,j]:
                q=deque([(i,j)]); seen[i,j]=True; c=[]
                while q:
